const stalls=[
 {name:'Cô Ba · Hàng cá',item:'Cá lóc',emoji:'🐟',goods:'🐟 🐟',price:45,color:'#598a8a',x:9,y:17,person:'👩🏻‍🌾',quote:'Cá lóc mới về sáng nay, nấu canh chua là hết sẩy!'},
 {name:'Dì Tư · Rau vườn',item:'Rau muống',emoji:'🥬',goods:'🥬 🥒',price:12,color:'#689456',x:64,y:17,person:'👩🏻',quote:'Rau vườn dì mới hái, mua đi dì cho thêm hành nè.'},
 {name:'Cô Sáu · Rau củ',item:'Cà chua',emoji:'🍅',goods:'🍅 🍆',price:15,color:'#c77454',x:9,y:70,person:'👩🏽‍🌾',quote:'Cà chua chín cây, đỏ au. Má con hay mua ở cô đó!'},
 {name:'Chú Năm · Gia vị',item:'Me chua',emoji:'🫘',goods:'🫘 🧄',price:10,color:'#bc9b4d',x:64,y:70,person:'👨🏻',quote:'Canh chua phải có chút me mới đúng vị nha con.'},
 {name:'Chị Út · Ăn vặt',item:'Bánh tráng trộn',emoji:'🥗',goods:'🥗 🧋',price:25,color:'#b47a91',x:65,y:44,person:'👩🏻‍🍳',quote:'Đi chợ mệt chưa? Một bịch bánh tráng cho có sức nè!'}
];
const required=stalls.slice(0,4),$=id=>document.getElementById(id);let state,active=null,timer;
function reset(){state={money:150,bag:[],bargained:{},ended:false};$('shop').close();$('player').style.left='46%';$('player').style.top='49%';render()}
function render(){$('money').textContent=state.money.toLocaleString('vi-VN')+'.000đ';$('list').innerHTML=required.map(s=>`<li class="${state.bag.includes(s.item)?'done':''}"><b>${state.bag.includes(s.item)?'☑':'□'}</b> ${s.emoji} ${s.item}<span style="margin-left:auto;font-size:9px">${s.item==='Cá lóc'?'1 con':s.item==='Rau muống'?'1 bó':s.item==='Cà chua'?'3 quả':'1 gói'}</span></li>`).join('');let n=required.filter(s=>state.bag.includes(s.item)).length;$('bar').style.width=n/4*100+'%';$('count').textContent=`Đã mua ${n}/4 món má dặn`;$('bagcount').textContent=state.bag.length+' món';$('bag').textContent=state.bag.length?state.bag.join(' · '):'Giỏ còn trống. Ghé một sạp nào!'}
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('toast').classList.remove('show'),3200)}
function visit(i){if(state.ended)return;active=i;const s=stalls[i];$('player').style.left=(s.x+9)+'%';$('player').style.top=(s.y>60?57:44)+'%';showShop();$('shop').showModal()}
function showShop(){const s=stalls[active],discount=state.bargained[active]||0,p=s.price-discount,owned=state.bag.includes(s.item);$('dialogContent').innerHTML=`<div class="portrait">${s.person}</div><p class="eyebrow">${s.name}</p><h2>${s.emoji} ${s.item}</h2><p class="quote">“${discount?'Thôi cô chú bớt cho con một chút. Lần sau ghé nữa nha!':s.quote}”</p><p>Giá: <strong>${p}.000đ</strong> ${discount?'<small>· Đã bớt '+discount+'.000đ</small>':''}</p><div class="actions"><button class="primary" id="buy" ${owned||state.money<p?'disabled':''}>${owned?'✓ Đã có trong giỏ':state.money<p?'Không đủ tiền':'Mua bỏ vào giỏ · '+p+'.000đ'}</button><button id="bargain" ${discount||owned?'disabled':''}>Cô chú bớt cho con chút nha!</button><button id="leave">Đi xem sạp khác</button></div>`;$('buy').onclick=()=>{if(state.bag.includes(s.item)||state.money<p)return;state.money-=p;state.bag.push(s.item);render();$('shop').close();toast(required.every(r=>state.bag.includes(r.item))?'Đủ đồ rồi! Chạm vào nhà để về với má.':'Đã bỏ '+s.item.toLowerCase()+' vào giỏ 🧺')};$('bargain').onclick=()=>{state.bargained[active]=Math.max(2,Math.round(s.price*.12));showShop()};$('leave').onclick=()=>$('shop').close()}
$('stalls').innerHTML=stalls.map((s,i)=>`<button class="stall" aria-label="Ghé ${s.name}" style="left:${s.x}%;top:${s.y}%;--color:${s.color}" data-i="${i}"><span class="awning"></span><span class="stand"><span class="goods">${s.goods}</span><span class="stall-name">${s.name}</span><span class="price">${s.price}.000đ · ${s.item}</span></span></button>`).join('');document.querySelectorAll('.stall').forEach(b=>b.onclick=()=>visit(+b.dataset.i));$('close').onclick=()=>$('shop').close();$('reset').onclick=reset;
$('home').onclick=()=>{if(state.ended){reset();return}const n=required.filter(s=>state.bag.includes(s.item)).length;if(n<4){toast(`Còn thiếu ${4-n} món má dặn. Mua đủ rồi về nha!`);return}state.ended=true;const snack=state.bag.includes('Bánh tráng trộn');$('dialogContent').innerHTML=`<div class="portrait">🏡</div><p class="eyebrow">BỮA CƠM NHÀ LÀ NGON NHẤT</p><h2>Má đợi con nãy giờ!</h2><p class="quote">“${snack?'Mua đủ hết mà sao tiền thừa có mùi bánh tráng trộn vậy?':'Giỏi quá! Mua đủ đồ, lại còn biết tiết kiệm cho má nữa.'}”</p><p>🌟 🌟 🌟<br>Đủ 4 món · Còn dư <strong>${state.money}.000đ</strong><br>${Object.keys(state.bargained).length} lần trả giá thành công.</p><div class="actions"><button class="primary" id="again">Đi chợ lần nữa ↻</button></div>`;$('again').onclick=reset;$('shop').showModal()};reset();
